//! Bundled embroidery fonts (the curated core set of the Tarz font
//! library). Every font is SIL Open Font License 1.1; see
//! `assets/fonts/LICENSES.md` for sources and versions. Font bytes are
//! embedded with `include_bytes!` so the engine works without any file
//! system (WASM).
//!
//! This table was generated by the Tarz Studio font pipeline (not part of
//! this repository); keep it in sync with `assets/fonts/fonts.json`.

pub(crate) struct Bundled {
    pub id: &'static str,
    pub name: &'static str,
    pub script: &'static str,
    pub style: &'static str,
    pub free: bool,
    pub min_size_mm: f64,
    pub data: &'static [u8],
    /// Pre-digitized glyphs (`.tzf`, may be empty).
    pub tzf: &'static [u8],
}

macro_rules! font {
    ($file:literal) => {
        include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/fonts/", $file))
    };
}

